import type { Meta, StoryObj } from "@storybook/nextjs-vite";

import { Icon, type IconName } from "./Icon";
import { icons } from "./icons.generated";

const NAMES = Object.keys(icons) as IconName[];

const meta = {
  title: "Atoms/Icon",
  component: Icon,
  parameters: {
    docs: {
      description: {
        component:
          "Figma: Design system › Icon/* (Hugeicons). Generated by `npm run icons`.",
      },
    },
  },
  args: { name: "add-01" },
  argTypes: { name: { control: "select", options: NAMES } },
} satisfies Meta<typeof Icon>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Single: Story = {};

export const All: Story = {
  parameters: { layout: "fullscreen", controls: { disable: true } },
  render: () => (
    <div className="grid grid-cols-[repeat(auto-fill,minmax(var(--space-16),1fr))] gap-4 bg-canvas p-6 text-ink-2">
      {NAMES.map((name) => (
        <figure key={name} className="flex flex-col items-center gap-2">
          <Icon name={name} />
          <figcaption className="text-center type-caption break-all text-ink-3">
            {name}
          </figcaption>
        </figure>
      ))}
    </div>
  ),
};

export const Sizes: Story = {
  parameters: { controls: { disable: true } },
  render: () => (
    <div className="flex items-center gap-4 text-ink-2">
      <Icon name="search-01" className="size-icon-sm" />
      <Icon name="search-01" className="size-icon-md" />
      <Icon name="search-01" className="size-6" />
    </div>
  ),
};
